	private static WorkbenchRequest request(String query, String accept, String acceptEncoding) throws Exception {
		return request(query, accept, acceptEncoding, null);
	}

	private static WorkbenchRequest request(String query, String accept, String acceptEncoding, String requestId)
			throws Exception {
		WorkbenchRequest request = mock(WorkbenchRequest.class);
		when(request.getParameter("action")).thenReturn("exec");
		when(request.isParameterPresent("action")).thenReturn(true);
		when(request.isParameterPresent(QueryServlet.REF)).thenReturn(false);
		when(request.isParameterPresent(QueryServlet.QUERY)).thenReturn(true);
		when(request.getParameter(QueryServlet.QUERY)).thenReturn(query);
		when(request.isParameterPresent("query-request-id")).thenReturn(requestId != null);
		when(request.getParameter("query-request-id")).thenReturn(requestId);
		when(request.getParameter("queryLn")).thenReturn("SPARQL");
		when(request.isParameterPresent("infer")).thenReturn(false);
		when(request.isParameterPresent("explain")).thenReturn(false);
		when(request.isParameterPresent("Accept")).thenReturn(accept != null);
		when(request.getParameter("Accept")).thenReturn(accept);
		when(request.getHeader("Accept")).thenReturn("application/sparql-results+xml");
		when(request.getHeader("Accept-Encoding")).thenReturn(acceptEncoding);
		when(request.getInt("offset")).thenReturn(0);
		when(request.getInt("limit_query")).thenReturn(0);
		when(request.getInt("know_total")).thenReturn(0);
		when(request.getInt("query-timeout")).thenReturn(0);
		when(request.getContextPath()).thenReturn("");
		return request;
	}

	private static void stubTupleQuery(RepositoryConnection connection, TupleQuery tupleQuery) {
		when(connection.prepareQuery(QueryLanguage.SPARQL, QUERY)).thenReturn(tupleQuery);
	}

	private static WorkbenchRequest pageDataRequest(String query) throws Exception {
		WorkbenchRequest request = request(query, null, null);
		Map<String, Object> attributes = new HashMap<>();
		when(request.getHeader("Accept")).thenReturn(WorkbenchPageProtocol.ACCEPT);
		doAnswer(invocation -> {
			attributes.put(invocation.getArgument(0), invocation.getArgument(1));
			return null;
		}).when(request).setAttribute(anyString(), any());
		when(request.getAttribute(anyString())).thenAnswer(invocation -> attributes.get(invocation.getArgument(0)));
		return request;
	}

	private static HttpServletResponse responseWith(ServletOutputStream output) throws IOException {
		HttpServletResponse response = mock(HttpServletResponse.class);
		when(response.getOutputStream()).thenReturn(output);
		return response;
	}

	private static RepositoryResult<Namespace> emptyNamespaces() {
		return new RepositoryResult<>(new CloseableIteratorIteration<>(List.<Namespace>of().iterator()));
	}

	private static org.eclipse.rdf4j.query.BindingSet binding(String value) {
		MapBindingSet bindingSet = new MapBindingSet();
		bindingSet.addBinding("s", SimpleValueFactory.getInstance().createIRI(value));
		return bindingSet;
	}

